#include <stdio.h>

int sum_recursive(int n) {
    if (n <= 0) return 0;
    return n + sum_recursive(n - 1);
}

int sum_loop(int n) {
    int total = 0;
    for (int i = 1; i <= n; i++) {
        total += i;
    }
    return total;
}

int main() {
    printf("Recursive: %d\n", sum_recursive(5));
    printf("Loop: %d\n", sum_loop(5));
    return 0;
}
